      body: "\n                   \n\n\n\n\n    Modules\n    AppModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\nLegend\n\n  Declarations\n\n  Module\n\n  Bootstrap\n\n  Providers\n\n  Exports\n\ncluster_AppModule\n\n\n\ncluster_AppModule_imports\n\n\n\n\nCoreModule\n\nCoreModule\n\n\n\nAppModule\n\nAppModule\n\nAppModule -->\n\nCoreModule->AppModule\n\n\n\n\n\nGatewayModule\n\nGatewayModule\n\nAppModule -->\n\nGatewayModule->AppModule\n\n\n\n\n\nMicroservicesModule\n\nMicroservicesModule\n\nAppModule -->\n\nMicroservicesModule->AppModule\n\n\n\n\n\nModulesModule\n\nModulesModule\n\nAppModule -->\n\nModulesModule->AppModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Imports\n                    \n                        \n                            CoreModule\n                        \n                        \n                            GatewayModule\n                        \n                        \n                            MicroservicesModule\n                        \n                        \n                            ModulesModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { Module } from '@nestjs/common';\nimport { CoreModule } from './core/core.module';\nimport { ConfigModule } from '@nestjs/config';\nimport { MongooseModule } from '@nestjs/mongoose';\nimport { MicroservicesModule } from './microservices/microservices.module';\nimport { GatewayModule } from './gateway/gateway.module';\nimport { ModulesModule } from './modules/modules.module';\n\n@Module({\n  imports: [\n    ConfigModule.forRoot(),\n    MongooseModule.forRoot(process.env.MONGO_DB_METADATA as string, {\n      connectionName: 'metadata',\n    }),\n    MongooseModule.forRoot(process.env.MONGO_DB_FIRESTORE as string, {\n      connectionName: 'firestore',\n    }),\n    CoreModule,\n    MicroservicesModule,\n    GatewayModule,\n    ModulesModule,\n  ],\n  controllers: [],\n  providers: [],\n})\nexport class AppModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
