    'injectables/AuthService.html': {
      url: 'injectables/AuthService.html',
      title: 'injectable - AuthService',
      body: "\n                   \n\n\n\n\n\n\n\n\n\n  Injectables\n  AuthService\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            src/modules/auth/auth.service.ts\n        \n\n\n\n\n\n            \n    Index\n    \n        \n\n                \n                    \n                        Methods\n                    \n                \n                \n                    \n                        \n                            \n                                    Async\n                                compileLogInResponse\n                            \n                        \n                    \n                \n\n\n\n\n\n        \n    \n\n\n            \n    Constructor\n        \n            \n                \n                    \nconstructor(jwtService: JwtService)\n                    \n                \n                        \n                            \n                                Defined in src/modules/auth/auth.service.ts:7\n                            \n                        \n\n                \n                    \n                            \n                                    Parameters :\n                                    \n                                        \n                                            \n                                                Name\n                                                    Type\n                                                Optional\n                                            \n                                        \n                                        \n                                                \n                                                        jwtService\n                                                  \n                                                        \n                                                                    JwtService\n                                                        \n                                                  \n                                                    \n                                                            No\n                                                    \n                                                    \n                                                \n                                        \n                                    \n                            \n                    \n                \n            \n        \n\n\n            \n    \n    \n        Methods\n    \n    \n        \n            \n                \n                    \n                    \n                            Async\n                        compileLogInResponse\n                        \n                    \n                \n            \n            \n                \n                        \n                    compileLogInResponse(user: User | undefined, ignoreRefreshToken: boolean)\n                \n            \n\n\n                    \n                        \n                            Defined in src/modules/auth/auth.service.ts:10\n                        \n                    \n\n\n            \n                \n\n                            \n                                Parameters :\n                                \n                                \n                                    \n                                        \n                                            Name\n                                                Type\n                                            Optional\n                                                Default value\n                                        \n                                    \n                                    \n                                        \n                                                user\n                                            \n                                                            User | undefined\n                                            \n\n                                            \n                                                    No\n                                            \n\n                                            \n                                            \n\n                                        \n                                        \n                                                ignoreRefreshToken\n                                            \n                                                            boolean\n                                            \n\n                                            \n                                                    No\n                                            \n\n                                            \n                                                    false\n                                            \n\n                                        \n                                    \n                                \n                            \n                        \n                            Returns :     Promise\n\n                        \n                            \n                                \n                            \n                \n            \n        \n    \n\n\n    \n\n\n    \n        import { Injectable } from '@nestjs/common';\nimport { User } from '../user/user.type';\nimport { JwtService } from '@nestjs/jwt';\nimport { JWTPayload, LogInResponseDto } from './auth.interface';\n\n@Injectable()\nexport class AuthService {\n  constructor(private readonly jwtService: JwtService) {}\n\n  async compileLogInResponse(\n    user: User | undefined,\n    ignoreRefreshToken: boolean = false,\n  ): Promise {\n    const payload: JWTPayload = {\n      type: 'dashboard',\n      sub: user?._id,\n      username: user?.username,\n      email: user?.email,\n    };\n    const accessToken = await this.jwtService.signAsync(payload);\n    const response: LogInResponseDto = {\n      accessToken: accessToken,\n      refreshToken: ignoreRefreshToken ? undefined : user?.refreshToken,\n      metadata: {\n        ...user,\n        refreshToken: undefined, //ignore refreshToken\n      },\n    };\n    return response;\n  }\n}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
    },
