    'modules/MicroservicesModule.html': {
      url: 'modules/MicroservicesModule.html',
      title: 'module - MicroservicesModule',
      body: "\n                   \n\n\n\n\n    Modules\n    MicroservicesModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\nLegend\n\n  Declarations\n\n  Module\n\n  Bootstrap\n\n  Providers\n\n  Exports\n\ncluster_MicroservicesModule\n\n\n\ncluster_MicroservicesModule_imports\n\n\n\n\nModulesModule\n\nModulesModule\n\n\n\nMicroservicesModule\n\nMicroservicesModule\n\nMicroservicesModule -->\n\nModulesModule->MicroservicesModule\n\n\n\n\n\nMsFirestoreModule\n\nMsFirestoreModule\n\nMicroservicesModule -->\n\nMsFirestoreModule->MicroservicesModule\n\n\n\n\n\nMsProjectModule\n\nMsProjectModule\n\nMicroservicesModule -->\n\nMsProjectModule->MicroservicesModule\n\n\n\n\n\nMsUserModule\n\nMsUserModule\n\nMicroservicesModule -->\n\nMsUserModule->MicroservicesModule\n\n\n\n\n\nMsWebsdkModule\n\nMsWebsdkModule\n\nMicroservicesModule -->\n\nMsWebsdkModule->MicroservicesModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/microservices/microservices.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Imports\n                    \n                        \n                            ModulesModule\n                        \n                        \n                            MsFirestoreModule\n                        \n                        \n                            MsProjectModule\n                        \n                        \n                            MsUserModule\n                        \n                        \n                            MsWebsdkModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { Module } from '@nestjs/common';\nimport { ConfigModule } from '@nestjs/config';\nimport { ClientsModule, Transport } from '@nestjs/microservices';\nimport { microserviceConfig } from 'src/config/microservice.config';\nimport { ModulesModule } from 'src/modules/modules.module';\nimport { MsProjectModule } from './ms-project/ms-project.module';\nimport { MsUserModule } from './ms-user/ms-user.module';\nimport { MsFirestoreModule } from './ms-firestore/ms-firestore.module';\nimport { MsWebsdkModule } from './ms-websdk/ms-websdk.module';\n\n@Module({\n  imports: [\n    ConfigModule.forRoot(),\n    ClientsModule.register([\n      {\n        name: microserviceConfig.auth.name,\n        transport: Transport.REDIS,\n        options: {\n          host: process.env.REDIS_HOST as string,\n          port: parseInt(process.env.REDIS_PORT as string),\n        },\n      },\n      {\n        name: microserviceConfig.firestore.name,\n        transport: Transport.REDIS,\n        options: {\n          host: process.env.REDIS_HOST as string,\n          port: parseInt(process.env.REDIS_PORT as string),\n        },\n      },\n      {\n        name: microserviceConfig.project.name,\n        transport: Transport.REDIS,\n        options: {\n          host: process.env.REDIS_HOST as string,\n          port: parseInt(process.env.REDIS_PORT as string),\n        },\n      },\n    ]),\n    ModulesModule,\n    MsProjectModule,\n    MsUserModule,\n    MsFirestoreModule,\n    MsWebsdkModule,\n  ],\n})\nexport class MicroservicesModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
    },
    'modules/ModulesModule.html': {
      url: 'modules/ModulesModule.html',
      title: 'module - ModulesModule',
      body: "\n                   \n\n\n\n\n    Modules\n    ModulesModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\nLegend\n\n  Declarations\n\n  Module\n\n  Bootstrap\n\n  Providers\n\n  Exports\n\ncluster_ModulesModule\n\n\n\ncluster_ModulesModule_imports\n\n\n\ncluster_ModulesModule_exports\n\n\n\n\nAuthModule\n\nAuthModule\n\n\n\nModulesModule\n\nModulesModule\n\nModulesModule -->\n\nAuthModule->ModulesModule\n\n\n\n\n\nDatabaseModule\n\nDatabaseModule\n\nModulesModule -->\n\nDatabaseModule->ModulesModule\n\n\n\n\n\nFirestoreModule\n\nFirestoreModule\n\nModulesModule -->\n\nFirestoreModule->ModulesModule\n\n\n\n\n\nProjectModule\n\nProjectModule\n\nModulesModule -->\n\nProjectModule->ModulesModule\n\n\n\n\n\nUserModule\n\nUserModule\n\nModulesModule -->\n\nUserModule->ModulesModule\n\n\n\n\n\nWebsdkModule\n\nWebsdkModule\n\nModulesModule -->\n\nWebsdkModule->ModulesModule\n\n\n\n\n\nAuthModule \n\nAuthModule \n\nAuthModule  -->\n\nModulesModule->AuthModule \n\n\n\n\n\nFirestoreModule \n\nFirestoreModule \n\nFirestoreModule  -->\n\nModulesModule->FirestoreModule \n\n\n\n\n\nProjectModule \n\nProjectModule \n\nProjectModule  -->\n\nModulesModule->ProjectModule \n\n\n\n\n\nUserModule \n\nUserModule \n\nUserModule  -->\n\nModulesModule->UserModule \n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/modules/modules.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Imports\n                    \n                        \n                            AuthModule\n                        \n                        \n                            DatabaseModule\n                        \n                        \n                            FirestoreModule\n                        \n                        \n                            ProjectModule\n                        \n                        \n                            UserModule\n                        \n                        \n                            WebsdkModule\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            AuthModule\n                        \n                        \n                            FirestoreModule\n                        \n                        \n                            ProjectModule\n                        \n                        \n                            UserModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { Module } from '@nestjs/common';\nimport { AuthModule } from './auth/auth.module';\nimport { ProjectModule } from './project/project.module';\nimport { FirestoreModule } from './firestore/firestore.module';\nimport { UserModule } from './user/user.module';\nimport { WebsdkModule } from './websdk/websdk.module';\nimport { DatabaseModule } from './database/database.module';\n\n@Module({\n  imports: [\n    AuthModule,\n    UserModule,\n    ProjectModule,\n    FirestoreModule,\n    WebsdkModule,\n    DatabaseModule,\n  ],\n  exports: [AuthModule, UserModule, ProjectModule, FirestoreModule],\n})\nexport class ModulesModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
    },
