      body: "\n                   \n\n\n\n\n    Modules\n    ProjectModule\n\n\n\n    \n        \n\n\n\n\n\ndependencies\n\nLegend\n\n  Declarations\n\n  Module\n\n  Bootstrap\n\n  Providers\n\n  Exports\n\ncluster_ProjectModule\n\n\n\ncluster_ProjectModule_imports\n\n\n\ncluster_ProjectModule_exports\n\n\n\ncluster_ProjectModule_providers\n\n\n\n\nProjectAppModule\n\nProjectAppModule\n\n\n\nProjectModule\n\nProjectModule\n\nProjectModule -->\n\nProjectAppModule->ProjectModule\n\n\n\n\n\nProjectAppModule \n\nProjectAppModule \n\nProjectAppModule  -->\n\nProjectModule->ProjectAppModule \n\n\n\n\n\nProjectService \n\nProjectService \n\nProjectService  -->\n\nProjectModule->ProjectService \n\n\n\n\n\nProjectService\n\nProjectService\n\nProjectModule -->\n\nProjectService->ProjectModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/modules/project/project.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Providers\n                    \n                        \n                            ProjectService\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            ProjectAppModule\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            ProjectAppModule\n                        \n                        \n                            ProjectService\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { Module } from '@nestjs/common';\nimport { ProjectAppModule } from './app/project-app.module';\nimport { ConfigModule } from '@nestjs/config';\nimport { ProjectService } from './project.service';\nimport { MongooseModule } from '@nestjs/mongoose';\nimport { Project, ProjectSchema } from './project.types';\n\n@Module({\n  imports: [\n    ConfigModule.forRoot(),\n    MongooseModule.forFeature(\n      [{ name: Project.name, schema: ProjectSchema }],\n      'metadata',\n    ),\n    ProjectAppModule,\n  ],\n  providers: [ProjectService],\n  exports: [ProjectService, ProjectAppModule],\n})\nexport class ProjectModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
