      url: 'classes/RuleCondition.html',
      title: 'class - RuleCondition',
      body: "\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n  Classes\n  RuleCondition\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n\n\n\n    \n        \n            File\n        \n        \n            src/modules/firestore/firestore-rule/firestore-rule.types.ts\n        \n\n\n\n\n\n\n            \n    Index\n    \n        \n                \n                    \n                        Properties\n                    \n                \n                \n                    \n                        \n                            \n                                    \n                                condition\n                            \n                            \n                                    \n                                    Optional\n                                customCondition\n                            \n                        \n                    \n                \n\n\n\n\n\n\n        \n    \n\n\n\n            \n    \n    \n        Properties\n    \n    \n        \n            \n                \n                    \n                    \n                            \n                        condition\n                        \n                    \n                \n            \n                \n                    \n                        Type :         RuleConditionType\n\n                    \n                \n                \n                    \n                        Decorators : \n                        \n                        \n                            @Prop({enum: RuleConditionType})\n                        \n                    \n                \n                    \n                        \n                                Defined in src/modules/firestore/firestore-rule/firestore-rule.types.ts:26\n                        \n                    \n\n\n        \n    \n    \n        \n            \n                \n                    \n                    \n                            \n                            Optional\n                        customCondition\n                        \n                    \n                \n            \n                \n                    \n                        Type :         string\n\n                    \n                \n                \n                    \n                        Decorators : \n                        \n                        \n                            @Prop()\n                        \n                    \n                \n                    \n                        \n                                Defined in src/modules/firestore/firestore-rule/firestore-rule.types.ts:29\n                        \n                    \n\n\n        \n    \n\n\n\n\n\n\n\n\n    \n\n\n    \n        import { Prop, Schema, SchemaFactory } from '@nestjs/mongoose';\nimport { AuditEntity } from '../../base/base.type';\nimport { SchemaTypes } from 'mongoose';\nimport { User } from '../../user/user.type';\n\nexport enum RuleType {\n  read = 'read',\n  create = 'create',\n  update = 'update',\n  delete = 'delete',\n}\n\nexport enum RuleConditionType {\n  require_auth = 'require_auth',\n  owner = 'owner',\n  allow = 'allow',\n  deny = 'deny',\n  custom = 'custom',\n}\n\n@Schema()\nexport class RuleCondition extends AuditEntity {\n  @Prop({\n    enum: RuleConditionType,\n  })\n  condition: RuleConditionType;\n\n  @Prop()\n  customCondition?: string;\n}\n\n@Schema({\n  timestamps: true,\n})\nexport class RawRule extends AuditEntity {\n  @Prop()\n  schema: string;\n\n  @Prop({\n    enum: RuleType,\n  })\n  type: RuleType;\n\n  @Prop({\n    type: SchemaTypes.Array,\n  })\n  conditions: RuleCondition[];\n\n  @Prop({\n    type: SchemaTypes.ObjectId,\n    ref: User.name,\n  })\n  user: User;\n}\n\nexport const RawRuleSchema = SchemaFactory.createForClass(RawRule);\n\n    \n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n",
